import{_ as t}from"./chunks/entity-picker.BuWRM8I6.js";import{_ as a,o,c as s,a3 as i}from"./chunks/framework.BlfGB29P.js";const g=JSON.parse('{"title":"Home Assistant entities","description":"Load, search and select HA entities in Blocks.","frontmatter":{"title":"Home Assistant entities","description":"Load, search and select HA entities in Blocks."},"headers":[],"relativePath":"en/projects/blocks-for-ha/entities.md","filePath":"en/projects/blocks-for-ha/entities.md","lastUpdated":1792852622000}'),n={name:"en/projects/blocks-for-ha/entities.md"};function r(l,e,d,c,h,p){return o(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="select-entities" tabindex="-1">Select entities <a class="header-anchor" href="#select-entities" aria-label="Permalink to &quot;Select entities&quot;">​</a></h1><p>Since <strong>0.1.44</strong>, matching action and target fields in simple and extended blocks open a searchable picker. A small arrow marks these fields. <strong>HA-Auswahl laden</strong> in the toolbar and <strong>Neu laden</strong> in the dialog refresh the read-only catalogues.</p><p><img src="'+t+'" alt="Entity picker with a search result"></p><p>The image uses simulated test entities and the German interface. Since 0.1.46, the interface follows the selected DE/EN/FR app language. Entity names retain their original HA installation language.</p><h2 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage&quot;">​</a></h2><ol><li>Click the entity ID inside a block.</li><li>Search by name or ID. All search words must match. The first 150 matches are displayed; narrow the search for larger lists.</li><li>Choose a result and press <strong>Übernehmen</strong> (Apply). Only applying changes the block. <strong>Abbrechen</strong> (Cancel) or Escape preserves the previous value.</li><li>Alternatively enter an ID such as <code>light.living_room</code> manually. This also works offline or for entities missing from the list.</li></ol><p>Results show the name, ID and current state with unit. States are a <strong>snapshot</strong>, not continuous monitoring or sensor-value blocks for an automation.</p><table tabindex="0"><thead><tr><th>Block</th><th>Selection</th></tr></thead><tbody><tr><td>State/numeric triggers and conditions</td><td>All loaded entities</td></tr><tr><td>Light with colour/brightness</td><td><code>light</code> only</td></tr><tr><td>HA script</td><td><code>script</code> only</td></tr><tr><td>Helper</td><td>Current helper type: <code>input_boolean</code>, <code>counter</code> or <code>timer</code></td></tr><tr><td>On/off/toggle, refresh entity, generic HA action</td><td>All loaded entities; still check action support in HA</td></tr></tbody></table><p>Action fields show actions reported by HA. Entity targets use domains from action metadata or the action name. Target selection follows <code>entity_id</code>, <code>device_id</code>, <code>area_id</code>, <code>floor_id</code> or <code>label_id</code>: entities, devices, areas, floors or labels. The last four catalogues are not filtered by action. <strong>Mehrere Ziele auswählen</strong> enables lists in supported fields. Manual IDs, JSON lists and supported Jinja templates remain available; multiline Jinja text is preserved in full. Changing target type does not rewrite existing IDs.</p><p>Scenes and helpers use matching entity domains; extended numeric thresholds offer sensors and numeric helpers, time fields offer time helpers and sensors. Manual numbers/clocks remain possible. Existing operation dropdowns remain available. Variable names, trigger IDs, attributes, free text and complex data do not receive generic HA selection. Changing an ID does not rewrite references within Jinja or JSON data. Without an action catalogue, common examples are explicitly identified as examples; unavailable target catalogues permit manual IDs.</p><h2 id="ha-app-and-data" tabindex="-1">HA app and data <a class="header-anchor" href="#ha-app-and-data" aria-label="Permalink to &quot;HA app and data&quot;">​</a></h2><p>Refresh the repository in the HA app store, install <strong>0.1.44</strong> and restart the app. The app requires <code>homeassistant_api: true</code> and uses the server-side <code>SUPERVISOR_TOKEN</code>. Entities and actions are read through the <a href="https://developers.home-assistant.io/docs/api/rest/" target="_blank" rel="noreferrer">REST API</a>, target registries through the <a href="https://developers.home-assistant.io/docs/api/websocket/" target="_blank" rel="noreferrer">WebSocket API</a>. Missing registry permissions affect the respective list. No token entry is required in the editor.</p><p>The browser receives selection metadata only: IDs, names, domains and entity state/unit. Other attributes and credentials are not forwarded. The endpoints read catalogues only and execute no HA actions. The server does not follow redirects carrying credentials.</p><p>The list comes from HA states, not the complete entity registry. Disabled or not-yet-available entities without a state may be absent. <code>unknown</code>/<code>unavailable</code> states are displayed when present. A refresh failure clears the previous list; existing block IDs remain intact.</p><p>JSON projects and YAML contain the selected field values. Catalogues, names, state previews and credentials are not persisted or exported. All 163 block types remain available. Download your browser project through <strong>Projekt sichern</strong> before updating; a source backup does not include browser sessions.</p><h2 id="local-development" tabindex="-1">Local development <a class="header-anchor" href="#local-development" aria-label="Permalink to &quot;Local development&quot;">​</a></h2><p>Install the Python dependency once with <code>python -m pip install --require-hashes -r requirements.txt</code>. Docker installs it automatically.</p><p><code>npm run dev</code> alone uses manual IDs. For a connection, additionally start Python 3 with <code>npm run entities</code>. Set <code>BLOCKS_HA_URL</code> (base address without <code>/api</code>, for example <code>http://homeassistant.local:8123</code>) and <code>BLOCKS_HA_TOKEN</code> only in the server environment. Vite at <code>127.0.0.1:4180</code> proxies requests to the bridge at <code>127.0.0.1:9001</code>. Never put credentials in source or project files.</p><p>Docker starts the bridge and frontend together. Outside HA, bind locally or use an authenticated frontend when credentials are configured; standalone user authentication is not included yet. HA ingress protects access inside HA.</p><h2 id="verification" tabindex="-1">Verification <a class="header-anchor" href="#verification" aria-label="Permalink to &quot;Verification&quot;">​</a></h2><p>Project/YAML compatibility, search, filters, cancel, manual entry, failure handling, mobile layout and the complete Docker chain were verified against a simulated HA server. A practical test in a real HA installation remains pending. Entity selection does not confirm that a particular device supports an action.</p>',21)])])}const f=a(n,[["render",r]]);export{g as __pageData,f as default};
